package io.knowledgebrain.gateway;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class SubmissionReviewProxyTest {
 String id="01a10000-0000-7000-8000-000000000000",base="/api/groups/"+id+"/studies/"+id+"/assignments/"+id+"/submissions/review-queue";
 @Test void exactReadRouteOnly(){assertEquals("collaboration",GatewayRoute.select("GET",base).service());for(var method:List.of("POST","PUT","PATCH","DELETE","HEAD"))assertNull(GatewayRoute.select(method,base));assertNull(GatewayRoute.select("GET",base+"/authors/"+id));}
 @Test void boundedExactFilterQueriesAreForwardedWithoutCallerAuthority()throws Exception{var f=new GroupProxyTest();f.init();for(var filter:List.of("ALL","NEEDS_FEEDBACK","HAS_FEEDBACK","RETRACTED_FEEDBACK","PENDING_RESUBMISSION")){var r=f.request("GET",base);r.setQueryString("filter="+filter+"&limit=100&after="+id);r.addHeader("Authorization","Bearer spoof");r.addHeader("X-Principal-Id",id);f.proxy.proxy(r);verify(f.transport).send(eq(new GatewayRoute("collaboration",base+"?filter="+filter+"&limit=100&after="+id)),eq("GET"),argThat(h->!h.containsKey("Authorization")&&!h.containsKey("X-Principal-Id")),any());}}
 @Test void malformedQueryAndNonemptyReadNeverReachTransport()throws Exception{var f=new GroupProxyTest();f.init();for(var query:List.of("filter=all","filter=","filter=ALL&filter=HAS_FEEDBACK","filter=ALL&authorId="+id,"limit=101","limit=0","limit=01","after="+id.toUpperCase(),"filter=ALL%26limit=100","filter=ALL&limit=1&limit=2","before=1")){var r=f.request("GET",base);r.setQueryString(query);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(r));}var body=f.request("GET",base);body.setContent("{}".getBytes());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(body));var other=f.request("GET",base.replace("/review-queue","/mine"));other.setQueryString("filter=ALL");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(other));verifyNoInteractions(f.transport);}
}
